import{_ as n,l as i,o as e,c as s,v as t,p as d,x as r,d as c,i as l,S as A}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"间接分支预测","description":"","frontmatter":{"title":"间接分支预测","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/indirect-branch-predict.md","filePath":"cs/indirect-branch-predict.md","lastUpdated":1789023840000}'),h={name:"cs/indirect-branch-predict.md"};function p(E,a,T,B,_,P){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="间接分支预测" tabindex="-1">间接分支预测 <a class="header-anchor" href="#间接分支预测" aria-label="Permalink to &quot;间接分支预测&quot;">​</a></h1><div class="epigraph"><p>虚调用和跳表的下一 PC 来自寄存器，不是立即数；目标缓冲按地址缓存上一次，相关间接则还要历史选出「哪一个目标」。</p><footer>—— 据 Chang, Hao, and Patt, Target Prediction for Indirect Jumps, ISCA 1997；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/perceptron-predictor">上一课</a>把条件方向做成特征点积，输出仍是跳或不跳。<a href="/cs/btb-ras">BTB</a> 对间接跳转只存一个目标：同一个 <code>jalr</code> 若在两次调用里走向两个虚函数，BTB 会来回颠簸。本课不重训感知器。缺口是：<strong>一个 PC 对应多个合法目标时，如何用历史选出下一个地址。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>面向对象的虚调用、解释器 <code>switch</code>、语言运行时的间接跳转：目标来自寄存器或内存，ISA 在译码前不知道。BTB 命中给的是「上次」，对双态目标大约 50%。返回已有 <a href="/cs/btb-ras">RAS</a>，不要把 <code>ret</code> 再塞进本课的表。缺口不是更准的条件 gshare，而是<strong>按（PC，历史）缓存目标 PC</strong>。</p><p><span class="marginnote">Chang–Hao–Patt 把目标预测做成带历史的表，而不是只靠 BTB 的单槽。ITTAGE 把 TAGE 的标签几何搬到目标上，是后日工程化，本课先钉「历史选目标」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>间接目标表（ITT）：索引 <code>hash(PC, GHR)</code> 或 <code>hash(PC, 局部历史)</code>，条目存完整目标 PC 与可选标签。命中则 IF 用该目标；核对寄存器算出的地址，错则更新该槽（或分配新槽）。可与 BTB 并行：ITT 未命中则退回 BTB 的「上次」。</p>',8)),(e(),d(A,null,{default:r(()=>[l(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PC%5B%22%E9%97%B4%E6%8E%A5%E8%B7%B3%E8%BD%AC%20PC%22%5D%20--%3E%20H%5B%22%E4%B8%8E%20GHR%20%E6%95%A3%E5%88%97%22%5D%0A%20%20H%20--%3E%20ITT%5B%22%E7%9B%AE%E6%A0%87%E8%A1%A8%22%5D%0A%20%20ITT%20--%3E%20TGT%5B%22%E9%A2%84%E6%B5%8B%E7%9B%AE%E6%A0%87%20PC%22%5D%0A%20%20BTB%5B%22BTB%20%E5%8D%95%E6%A7%BD%E5%90%8E%E5%A4%87%22%5D%20--%3E%20TGT%0A%20%20TGT%20--%3E%20CHK%5B%22%E4%B8%8E%E7%9C%9F%E5%AE%9E%E5%AF%84%E5%AD%98%E5%99%A8%E7%9B%AE%E6%A0%87%E6%A0%B8%E5%AF%B9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>RAS 优先于 ITT：调用/返回配对不是「多目标相关」，是栈。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>条件预测错只冲刷方向；间接错则连取指流都走错页，损失拍数通常更大。面向对象程序的 CPI 往往被这里钉住，而不是被 <code>beq</code>。表项要存完整地址（或至少虚页内偏移 + 标签），比两位计数器贵。别名会把 A 的目标填进 B 的槽，表现为「跳进错误函数」——架构上仍会核对并冲刷，只是浪费窗口。</p><p>推测：ITT 的更新与 GHR 一样，误预测路径上的间接会污染；检查点或在提交时才写表。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 CFI / 间接跳转检查当预测器：那是安全课的落点，预测错了会冲刷，恶意目标是另一威胁模型。也不展开 ITTAGE 的每一张几何表。循环里「迭代 \\(N\\) 次后改变方向」是下一课循环预测器，与间接表正交。</p><p>后课默认：间接目标用历史选槽；返回用 RAS。方向与目标是两套结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多目标间接不能只靠 BTB 单槽；用（PC，历史）缓存目标。</li><li>返回继续走 RAS，不要与虚调用混表。</li><li>固定迭代次数的条件分支是下一课循环预测。</li><li>出处：Chang, Hao, and Patt, <em>ISCA</em>, 1997；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const f=n(h,[["render",p]]);export{C as __pageData,f as default};
